if (page === 'delete-account') {
  return [{
    json: {
      html: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Delete Cloud Data — Sangha Friend Tracker</title>
  <style>
    body { font-family: system-ui, -apple-system, sans-serif; background: #fafaf9; color: #1c1917; max-width: 680px; margin: 0 auto; padding: 32px 20px; line-height: 1.6; }
    .card { background: #ffffff; border: 1px solid #e7e5e4; border-radius: 16px; padding: 24px; box-shadow: 0 2px 6px rgba(0,0,0,0.05); }
    h1 { color: #b45309; margin-top: 0; }
    input, button { width: 100%; padding: 12px 14px; border-radius: 10px; font-size: 15px; box-sizing: border-box; margin-top: 10px; }
    input { border: 1px solid #d6d3d1; }
    button { background: #e11d48; color: #fff; border: none; font-weight: 700; cursor: pointer; margin-top: 16px; }
    pre { background: #f5f5f4; padding: 12px; border-radius: 8px; overflow-x: auto; font-size: 13px; }
  </style>
</head>
<body>
  <div class="card">
    <h1>Self-Service Cloud Account &amp; Data Deletion Portal</h1>
    <p><a href="/webhook/bsg-sangha-app" style="color:#d97706;font-weight:700;">&larr; Return to Sangha Friend Tracker</a></p>
    <p>Enter a Member or District Leader email address below to permanently purge matching records from the Cloud PostgreSQL Vault (GDPR Art. 17 &amp; Google Play Data Deletion Policy).</p>
    <input id="emailInput" type="email" placeholder="user@example.com" required />
    <button onclick="submitErasure()">Permanently Erase Cloud Data &amp; Issue Receipt</button>
    <div id="resultBox" style="margin-top:16px;"></div>
  </div>
  <script>
    async function submitErasure() {
      const email = document.getElementById('emailInput').value.trim();
      if (!email) return;
      const res = await fetch('/webhook/bsg-sangha-api', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'GDPR_ERASURE', payload: { email } })
      });
      const data = await res.json();
      document.getElementById('resultBox').innerHTML =
        '<strong>Cryptographic Cloud Erasure Complete:</strong><pre>' + JSON.stringify(data, null, 2) + '</pre>';
    }
  </script>
</body>
</html>`
    }
  }];
}

