    <button class="dock-item" data-dock="prospects" onclick="switchTab('prospects')"><span class="dock-icon">🌱</span>Seekers</button>
    <button class="dock-item" data-dock="members" onclick="switchTab('members')"><span class="dock-icon">🙏</span>Members</button>
    <button class="dock-item" data-dock="zadankai" onclick="switchTab('zadankai')"><span class="dock-icon">🌸</span>Zadankai</button>
    <button class="dock-item" data-dock="guidance" onclick="switchTab('guidance')"><span class="dock-icon">📚</span>Study OCR</button>
    <button class="dock-item" data-dock="chat" onclick="switchTab('chat')"><span class="dock-icon">🪷</span>AI Chat</button>
