  <script>
    const API_ENDPOINT = '/webhook/bsg-sangha-api';
    let state = { members: [], prospects: [], zadankai: [], guidance: [], daimokuWeekly: [], daimokuMonthly: [] };
    let chartMode = 'weekly';
    let availableMinutes = 60;
    let userCoords = { lat: 22.5726, lng: 88.3639 };
    let activeTimers = {};
    let pendingAchievement = null;
    let chatMessages = [
      {
        sender: 'ai',
        text: 'Nam-myoho-renge-kyo! Welcome to Sangha Friend Tracker (Bodhisattva’s Way v3.0). All district records are 100% persisted in the Cloud PostgreSQL Vault. Select a prompt above or ask how to encourage any member!'
      }
    ];

    const QUOTES = [
      '“Chanting Nam-myoho-renge-kyo with the spirit of Many in Body, One in Mind (Itai Doshin).”',
      '“Winter always turns to spring. Never, from ancient times on, has anyone heard or seen of winter turning back into autumn.” (WND-1, p. 536)',
      '“The greater the hardships befalling him, the greater the delight he feels, because of his strong faith.” (WND-1, p. 1000)',
      '“A great human revolution in just a single individual will help achieve a change in the destiny of a nation.”'
    ];
    let quoteIndex = 0;
    setInterval(() => {
      quoteIndex = (quoteIndex + 1) % QUOTES.length;
      const el = document.getElementById('rotatingQuoteBanner');
      if (el) el.textContent = QUOTES[quoteIndex];
    }, 7000);

    async function callCloudApi(action, payload = {}) {
      const badge = document.getElementById('cloudSyncBadge');
      if (badge) badge.textContent = '☁️ Syncing Cloud...';
      const res = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, payload })
      });
      const data = await res.json();
      if (data.state) {
        state = data.state;
        renderAll();
      }
      if (badge) badge.textContent = '☁️ 100% Cloud PostgreSQL Synced';
      return data;
    }

    function switchTab(tabKey) {
      document.querySelectorAll('.tab-pane').forEach(el => el.classList.add('hidden'));
      document.getElementById('pane-' + tabKey).classList.remove('hidden');
      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-tab') === tabKey);
      });
      document.querySelectorAll('.dock-item').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-dock') === tabKey);
      });
    }

    function formatClock(totalSeconds) {
      const s = Math.max(0, parseInt(totalSeconds || 0, 10));
      const hrs = Math.floor(s / 3600);
      const mins = Math.floor((s % 3600) / 60);
      const secs = s % 60;
      return String(hrs).padStart(2, '0') + ':' + String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
    }

    function renderAll() {
      const totalSecs = (state.prospects || []).reduce((acc, p) => acc + (p.chantingSeconds || 0), 0);
      const totalMins = Math.floor(totalSecs / 60);
      document.getElementById('daimokuBannerPill').textContent = '🔥 Dedicated Daimoku: ' + totalMins + ' mins';
      renderDaimokuChart();
      renderOutreachSuggestions();
      renderProspects();
      renderMembers();
      renderZadankaiHistory();
      renderGuidanceLibrary();
      renderChat();
    }

    function setChartMode(mode) {
      chartMode = mode;
      document.getElementById('btnWeekly').classList.toggle('active', mode === 'weekly');
      document.getElementById('btnMonthly').classList.toggle('active', mode === 'monthly');
      renderDaimokuChart();
    }

    function renderDaimokuChart() {
      const series = chartMode === 'weekly' ? (state.daimokuWeekly || []) : (state.daimokuMonthly || []);
      const box = document.getElementById('daimokuChartBox');
      box.innerHTML = series.map(item => {
        const h = Math.max(22, Math.min(125, Math.round(item.minutes / (chartMode === 'weekly' ? 2.5 : 8))));
        return `<div class="bar-col">
          <div style="font-size:11.5px;font-weight:800;color:#b45309;margin-bottom:5px;">${item.minutes}m</div>
          <div class="bar-rect" style="height:${h}px;"></div>
          <div style="font-size:11.5px;color:#57534e;margin-top:6px;font-weight:600;">${item.label}</div>
        </div>`;
      }).join('');
    }

    function selectTimeWindow(mins, btnEl) {
      availableMinutes = mins;
      btnEl.parentElement.querySelectorAll('.btn-sec').forEach(b => b.classList.remove('active'));
      btnEl.classList.add('active');
      renderOutreachSuggestions();
    }

    function syncLiveGps() {
      if (!navigator.geolocation) {
        alert('Using Kolkata District Center coordinates (22.5726, 88.3639).');
        return;
      }
      navigator.geolocation.getCurrentPosition(
        pos => {
          userCoords = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          renderOutreachSuggestions();
        },
        () => {
          renderOutreachSuggestions();
        }
      );
    }

    function haversineKm(lat1, lon1, lat2, lon2) {
      const R = 6371;
      const dLat = (lat2 - lat1) * Math.PI / 180;
      const dLon = (lon2 - lon1) * Math.PI / 180;
      const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                Math.sin(dLon / 2) * Math.sin(dLon / 2);
      return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(Math.max(0, 1 - a)));
    }

    function renderOutreachSuggestions() {
      const list = (state.members || []).filter(m => m.isActive !== false).map(m => {
        const dist = haversineKm(userCoords.lat, userCoords.lng, m.lat || 22.5726, m.lng || 88.3639);
        let score = 50;
        const reasons = [];
        if (dist < 3) { score += 30; reasons.push(`Very close (${dist.toFixed(1)} km).`); }
        else if (dist < 8) { score += 15; reasons.push(`Nearby (${dist.toFixed(1)} km).`); }
        else { score -= 10; reasons.push(`Further away (${dist.toFixed(1)} km).`); }

        if (m.challengeStatus === 'Active') {
          score += 25;
          reasons.push(`Urgent: Active challenge ("${(m.activeChallenge || '').slice(0, 44)}...").`);
        } else if (m.challengeStatus === 'Improved') {
          score += 10;
          reasons.push('Follow-up: Challenge improving, keep encouraging!');
        }

        let action = 'Quick Call / Msg';
        if (availableMinutes >= 60 && dist < 5) {
          action = 'Personal Visit';
          score += 10;
          if (m.visitPref) reasons.push(`Matches visit window (${m.visitPref}).`);
        } else if (availableMinutes >= 30) {
          action = 'Phone Call';
          if (m.callPref) reasons.push(`Preferred call time: ${m.callPref}.`);
        }
        return { member: m, score: Math.min(100, Math.max(10, score)), distanceKm: dist.toFixed(1), action, reason: reasons.join(' ') };
      }).sort((a, b) => b.score - a.score);

      document.getElementById('outreachSuggestionsBox').innerHTML = list.map(item => `
        <div class="subcard">
          <div class="row-between">
            <div>
              <h3>${item.member.name}</h3>
              <span style="font-size:11.5px;color:#78716c;">${item.member.district}</span>
            </div>
            <span class="pill ${item.action === 'Personal Visit' ? 'pill-emerald' : 'pill-amber'}">${item.action} • ${item.distanceKm} km (Score ${item.score})</span>
          </div>
          <p style="font-size:12.5px;margin:8px 0;color:#44403c;">${item.reason}</p>
          <div class="row">
            <a class="btn-sec" href="tel:${item.member.phone}">📞 Call</a>
            <a class="btn-sec" href="mailto:${item.member.email}">✉️ Email</a>
            <button class="btn-sec" onclick="switchTab('chat'); askAi('Give me Gosho encouragement and home-visit talking points for ${item.member.name}')">✨ AI Visit Prep</button>
          </div>
        </div>
      `).join('');
    }

    function renderProspects() {
      const box = document.getElementById('prospectsContainer');
      box.innerHTML = (state.prospects || []).map(p => {
        const running = Boolean(activeTimers[p.id]);
        return `<div class="subcard">
          <div class="row-between">
            <div>
              <h3>${p.name}</h3>
              <p style="font-size:12.5px;color:#44403c;margin:4px 0;">${p.initialLifeChallenge}</p>
            </div>
            <select onchange="updateProspectStatus('${p.id}', this.value)" style="width:auto;margin:0;font-weight:700;">
              ${['Introduction', 'Chanting', 'Attended Meeting', 'Received Gohonzon', 'Inactive'].map(st =>
                `<option value="${st}" ${p.status === st ? 'selected' : ''}>${st}</option>`
              ).join('')}
            </select>
          </div>
          <div class="row-between" style="margin-top:12px;background:#fff;padding:12px;border-radius:12px;border:1px solid var(--border);">
            <div>
              <span style="font-size:10.5px;text-transform:uppercase;color:#78716c;font-weight:700;display:block;">Cumulative Daimoku Chanted</span>
              <span class="timer-display" id="timer-${p.id}">${formatClock(p.chantingSeconds)}</span>
            </div>
            <div class="row">
              <button class="btn ${running ? 'btn-rose' : ''}" onclick="toggleSeekerTimer('${p.id}')">
                ${running ? '⏸ Pause & Save to Cloud' : '▶ Start Live Daimoku'}
              </button>
              <button class="btn-sec" onclick="logQuickMinutes('${p.id}', 900)">+15m Daimoku</button>
              <button class="btn-sec" onclick="switchTab('chat'); askAi('Suggest an encouraging Gosho concept for Shakabuku seeker ${p.name} who is chanting for: ${p.initialLifeChallenge}')">✨ AI Advice (v3.0)</button>
            </div>
          </div>
        </div>`;
      }).join('');
    }

    function toggleSeekerTimer(prospectId) {
      if (activeTimers[prospectId]) {
        clearInterval(activeTimers[prospectId].interval);
        const elapsed = activeTimers[prospectId].elapsed;
        delete activeTimers[prospectId];
        callCloudApi('LOG_DAIMOKU_TIMER', { prospectId, addedSeconds: elapsed });
      } else {
        activeTimers[prospectId] = {
          elapsed: 0,
          interval: setInterval(() => {
            activeTimers[prospectId].elapsed += 1;
            const p = (state.prospects || []).find(x => x.id === prospectId);
            if (p) {
              p.chantingSeconds = (p.chantingSeconds || 0) + 1;
              const el = document.getElementById('timer-' + prospectId);
              if (el) el.textContent = formatClock(p.chantingSeconds);
            }
          }, 1000)
        };
        renderProspects();
      }
    }

    function logQuickMinutes(prospectId, addedSeconds) {
      callCloudApi('LOG_DAIMOKU_TIMER', { prospectId, addedSeconds });
    }

    function updateProspectStatus(prospectId, status) {
      const p = (state.prospects || []).find(x => x.id === prospectId);
      if (!p) return;
      callCloudApi('UPSERT_PROSPECT', Object.assign({}, p, { status }));
    }

    function openProspectModal() {
      document.getElementById('prospectModal').classList.remove('hidden');
    }

    function submitNewProspect() {
      const name = document.getElementById('pName').value.trim();
      const initialLifeChallenge = document.getElementById('pChallenge').value.trim();
      const status = document.getElementById('pStatus').value;
      if (!name) return;
      document.getElementById('prospectModal').classList.add('hidden');
      callCloudApi('UPSERT_PROSPECT', { name, initialLifeChallenge, status, chantingSeconds: 0 });
    }

    function renderMembers() {
      const q = (document.getElementById('memberSearchInput')?.value || '').toLowerCase();
      const stFilter = document.getElementById('memberStatusFilter')?.value || 'All';
      const distFilter = document.getElementById('memberDistrictFilter')?.value || 'All';

      const filtered = (state.members || []).filter(m => {
        if (stFilter !== 'All' && m.challengeStatus !== stFilter) return false;
        if (distFilter !== 'All' && m.district !== distFilter) return false;
        if (q && !(m.name.toLowerCase().includes(q) || (m.district || '').toLowerCase().includes(q) || (m.activeChallenge || '').toLowerCase().includes(q))) return false;
        return true;
      });

      document.getElementById('membersContainer').innerHTML = filtered.map(m => {
        const pillClass = m.challengeStatus === 'Accomplished' ? 'pill-emerald' : (m.challengeStatus === 'Improved' ? 'pill-blue' : 'pill-amber');
        const historyHtml = (m.statusHistory || []).map(h =>
          `<div style="margin-bottom:6px;"><strong>${h.status}</strong> <span style="color:#78716c;">(${String(h.changedAt || '').slice(0, 10)})</span>: ${h.notes}</div>`
        ).join('');
        return `<div class="subcard">
          <div class="row-between">
            <div>
              <h3>${m.name} <span style="font-size:12px;font-weight:500;color:#78716c;">• ${m.district}</span></h3>
              <div style="font-size:12px;color:#78716c;margin-top:2px;">📍 ${m.address || 'Kolkata'} &bull; 🕒 Visit: ${m.visitPref || 'Anytime'} &bull; 📞 Call: ${m.callPref || 'Evenings'}</div>
            </div>
            <span class="pill ${pillClass}">${m.challengeStatus}</span>
          </div>
          <div style="font-size:13px;margin-top:8px;"><strong>Life Challenge:</strong> ${m.activeChallenge}</div>
          ${m.resolutionNotes ? `<div style="font-size:13px;margin-top:6px;color:#065f46;background:#d1fae5;padding:8px 12px;border-radius:10px;font-weight:600;">🏆 Breakthrough Victory: ${m.resolutionNotes}</div>` : ''}
          ${historyHtml ? `<details style="margin-top:8px;"><summary style="font-size:12px;font-weight:700;color:#b45309;cursor:pointer;">📜 View Status Recovery Timeline (${(m.statusHistory || []).length} logs)</summary><div class="history-timeline">${historyHtml}</div></details>` : ''}
          <div class="row" style="margin-top:10px;">
            <button class="btn-sec" onclick="openAchievementModal('${m.id}', 'Improved')">📈 Mark Improved</button>
            <button class="btn-sec" onclick="openAchievementModal('${m.id}', 'Accomplished')">🏆 Log Victory (Accomplished)</button>
            <a class="btn-sec" href="tel:${m.phone}">📞 Call</a>
            <button class="btn-sec" onclick="switchTab('chat'); askAi('Give me Gosho encouragement for ${m.name}')">✨ AI Care Advice</button>
          </div>
        </div>`;
      }).join('');
    }

    function openAchievementModal(memberId, targetStatus) {
      const m = (state.members || []).find(x => x.id === memberId);
      if (!m) return;
      pendingAchievement = { member: m, status: targetStatus };
      document.getElementById('achievementModalSubtitle').textContent =
        `Recording "${targetStatus}" breakthrough for ${m.name} (${m.district}):`;
      document.getElementById('achievementNotesInput').value = m.resolutionNotes || '';
      document.getElementById('achievementModal').classList.remove('hidden');
    }

    function closeAchievementModal() {
      pendingAchievement = null;
      document.getElementById('achievementModal').classList.add('hidden');
    }

    function confirmAchievementBreakthrough() {
      if (!pendingAchievement) return;
      const notes = document.getElementById('achievementNotesInput').value.trim() ||
        `Achieved ${pendingAchievement.status} breakthrough through resolute Daimoku!`;
      const m = pendingAchievement.member;
      const updated = Object.assign({}, m, {
        challengeStatus: pendingAchievement.status,
        resolutionNotes: notes,
        statusHistory: (m.statusHistory || []).concat([{
          id: 'sh-' + Date.now(),
          status: pendingAchievement.status,
          notes,
          changedAt: new Date().toISOString()
        }])
      });
      closeAchievementModal();
      callCloudApi('UPSERT_MEMBER', updated);
    }

    function openMemberModal() {
      document.getElementById('memberModal').classList.remove('hidden');
    }

    function submitNewMember() {
      const name = document.getElementById('mName').value.trim();
      if (!name) return;
      const newMember = {
        name,
        phone: document.getElementById('mPhone').value.trim(),
        email: document.getElementById('mEmail').value.trim(),
        district: document.getElementById('mDistrict').value,
        visitPref: document.getElementById('mVisitPref').value.trim(),
        callPref: document.getElementById('mCallPref').value.trim(),
        activeChallenge: document.getElementById('mChallenge').value.trim(),
        challengeStatus: 'Active',
        resolutionNotes: '',
        lat: 22.58,
        lng: 88.41,
        isActive: true
      };
      document.getElementById('memberModal').classList.add('hidden');
      callCloudApi('UPSERT_MEMBER', newMember);
    }

    function exportMembersJson() {
      const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'bsg_sangha_cloud_backup.json';
      a.click();
    }

    function exportMembersCsv() {
      const headers = ['ID', 'Name', 'District', 'ChallengeStatus', 'ActiveChallenge', 'ResolutionNotes'];
      const rows = (state.members || []).map(m => [
        m.id, m.name, m.district, m.challengeStatus,
        '"' + String(m.activeChallenge || '').replace(/"/g, '""') + '"',
        '"' + String(m.resolutionNotes || '').replace(/"/g, '""') + '"'
      ].join(','));
      const csv = [headers.join(',')].concat(rows).join('\n');
      const blob = new Blob([csv], { type: 'text/csv' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'bsg_sangha_members.csv';
      a.click();
    }

    async function generateAiZadankaiRoles() {
      const data = await callCloudApi('ZADANKAI_ROTATION', { targetMonth: document.getElementById('zMonth').value });
      const banner = document.getElementById('zadankaiAiBanner');
      banner.classList.remove('hidden');
      banner.innerHTML = `<div class="subcard" style="background:var(--amber-subtle);border-color:#f59e0b;margin-bottom:12px;">
        <strong>✨ AI Role Rotation Auto-Filled (${data.districtConceptTheme}):</strong>
        <ul style="margin:6px 0;padding-left:18px;font-size:12px;">
          ${(data.recommendations || []).map(r => `<li><strong>${r.role}:</strong> ${r.memberIdOrName} — <em>${r.explanation}</em></li>`).join('')}
        </ul>
      </div>`;
      (data.recommendations || []).forEach(r => {
        if (r.role === 'Emcee') document.getElementById('zEmcee').value = r.memberIdOrName;
        if (r.role === 'Significance') document.getElementById('zSignificance').value = r.memberIdOrName;
        if (r.role === 'Festoon') document.getElementById('zFestoon').value = r.memberIdOrName;
        if (r.role === 'Song') document.getElementById('zSong').value = r.memberIdOrName;
        if (r.role === 'FD Activity') document.getElementById('zFd').value = r.memberIdOrName;
        if (r.role === 'Experience') document.getElementById('zExperience').value = r.memberIdOrName;
      });
      if (data.districtConceptTheme) document.getElementById('zConcept').value = data.districtConceptTheme;
    }

    function saveZadankaiPlan() {
      const rec = {
        month: document.getElementById('zMonth').value.trim(),
        emceeId: document.getElementById('zEmcee').value.trim(),
        significanceId: document.getElementById('zSignificance').value.trim(),
        festoonId: document.getElementById('zFestoon').value.trim(),
        songId: document.getElementById('zSong').value.trim(),
        fdActivityId: document.getElementById('zFd').value.trim(),
        experienceId: document.getElementById('zExperience').value.trim(),
        vcConnectTimes: document.getElementById('zVcTimes').value.trim(),
        concept: document.getElementById('zConcept').value.trim(),
        guidance: document.getElementById('zGuidance').value.trim()
      };
      callCloudApi('UPSERT_ZADANKAI', rec);
    }

    function shareCurrentZadankai() {
      const text = `🌸 *BSG District Zadankai Plan — ${document.getElementById('zMonth').value}* 🌸\n` +
        `✨ *Theme:* ${document.getElementById('zConcept').value}\n\n` +
        `🎙️ *Emcee:* ${document.getElementById('zEmcee').value}\n` +
        `📖 *Significance:* ${document.getElementById('zSignificance').value}\n` +
        `🏮 *Festoon:* ${document.getElementById('zFestoon').value}\n` +
        `🎵 *Song:* ${document.getElementById('zSong').value}\n` +
        `🌱 *FD Activity:* ${document.getElementById('zFd').value}\n` +
        `🌟 *Victory Experience:* ${document.getElementById('zExperience').value}\n` +
        `💻 *VC Connect Times:* ${document.getElementById('zVcTimes').value}\n\n` +
        `📜 *Study Guidance:* "${document.getElementById('zGuidance').value}"`;
      if (navigator.share) {
        navigator.share({ title: 'BSG Zadankai Plan', text });
      } else {
        navigator.clipboard.writeText(text);
        alert('Privacy-safe WhatsApp Zadankai Role Matrix copied to clipboard!');
      }
    }

    function renderZadankaiHistory() {
      document.getElementById('zadankaiHistoryBox').innerHTML = (state.zadankai || []).map(z => `
        <div class="subcard">
          <div class="row-between">
            <h3>🗓️ ${z.month}: ${z.concept}</h3>
            <span class="pill pill-amber">${z.vcConnectTimes}</span>
          </div>
          <div style="font-size:12.5px;margin-top:8px;line-height:1.6;">
            🎙️ <strong>Emcee:</strong> ${z.emceeId} &bull;
            📖 <strong>Significance:</strong> ${z.significanceId} &bull;
            🏮 <strong>Festoon:</strong> ${z.festoonId}<br/>
            🎵 <strong>Song:</strong> ${z.songId} &bull;
            🌱 <strong>FD Activity:</strong> ${z.fdActivityId} &bull;
            🌟 <strong>Experience:</strong> ${z.experienceId}
          </div>
          <div style="font-size:12px;color:#78716c;margin-top:6px;font-style:italic;">“${z.guidance}”</div>
        </div>
      `).join('');
    }

    async function processStudyOcr() {
      const btn = document.getElementById('btnProcessOcr');
      btn.textContent = '⏳ Extracting Gosho Text...';
      await callCloudApi('SUMMARIZE_STUDY_IMAGE', {});
      btn.textContent = '✨ Process & Extract Text (Cloud OCR)';
    }

    async function transcribeVoiceReflection() {
      await callCloudApi('TRANSCRIBE_VOICE_MEMO', {});
    }

    function saveCustomGuidance() {
      const category = document.getElementById('gCategory').value.trim() || 'Faith & Practice';
      const rawText = document.getElementById('gRawText').value.trim();
      const summaryText = document.getElementById('gSummaryText').value.trim();
      if (!rawText) return;
      document.getElementById('gRawText').value = '';
      document.getElementById('gSummaryText').value = '';
      callCloudApi('UPSERT_GUIDANCE', { category, rawText, summaryText: summaryText || ('• ' + rawText.slice(0, 80)) });
    }

    function renderGuidanceLibrary() {
      document.getElementById('guidanceLibraryBox').innerHTML = (state.guidance || []).map(g => `
        <div class="subcard">
          <div class="row-between">
            <span class="pill pill-amber">📖 ${g.category}</span>
            <span style="font-size:11px;color:#78716c;">${String(g.createdAt || '').slice(0, 10)}</span>
          </div>
          <div style="font-size:13px;margin-top:8px;white-space:pre-line;font-weight:600;color:#1c1917;">${g.summaryText}</div>
          <div style="font-size:12px;color:#57534e;margin-top:6px;font-style:italic;">“${g.rawText}”</div>
        </div>
      `).join('');
    }

    async function askAi(queryText) {
      const q = String(queryText || '').trim();
      if (!q) return;
      document.getElementById('chatQueryInput').value = '';
      chatMessages.push({ sender: 'user', text: q });
      renderChat();
      const data = await callCloudApi('BODHISATTVA_CHAT', { query: q });
      chatMessages.push({ sender: 'ai', text: data.reply || 'Chanting Nam-myoho-renge-kyo for your district victory!' });
      renderChat();
    }

    function renderChat() {
      const box = document.getElementById('chatMessagesBox');
      box.innerHTML = chatMessages.map(m => `
        <div class="subcard" style="background:${m.sender === 'user' ? 'var(--amber-light)' : '#fff'};margin-left:${m.sender === 'user' ? '40px' : '0'};margin-right:${m.sender === 'ai' ? '40px' : '0'};">
          <strong style="font-size:11.5px;color:#b45309;">${m.sender === 'user' ? '👤 District Leader' : '🪷 Bodhisattva AI v3.0'}</strong>
          <div style="font-size:13px;margin-top:4px;white-space:pre-wrap;line-height:1.55;">${m.text}</div>
        </div>
      `).join('');
      box.scrollTop = box.scrollHeight;
    }

    // Initial Cloud State Load
    callCloudApi('SYNC_STATE');
  </script>
</body>
</html>";

return [{ json: { html: appHtml } }];

parameters.query:
CREATE TABLE IF NOT EXISTS bsg_sangha_cloud_store (
    store_key VARCHAR(64) PRIMARY KEY,
    state_json JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
SELECT state_json FROM bsg_sangha_cloud_store WHERE store_key = 'primary_district_state' LIMIT 1;

