const pgItem = $input.first()?.json || {};
let state = pgItem.state_json ? JSON.parse(JSON.stringify(pgItem.state_json)) : JSON.parse(JSON.stringify(SEED_STATE));
if (!Array.isArray(state.members)) state = JSON.parse(JSON.stringify(SEED_STATE));

let extraResponse = {};

if (action === 'UPSERT_MEMBER') {
  const m = Object.assign({}, payload);
  if (!m.id) m.id = 'm-' + Date.now();
  if (!m.createdAt) m.createdAt = new Date().toISOString();
  if (!Array.isArray(m.statusHistory)) {
    m.statusHistory = [{ id: 'sh-' + Date.now(), status: m.challengeStatus || 'Active', notes: m.activeChallenge || 'Registered in Cloud Directory.', changedAt: m.createdAt }];
  }
  const idx = state.members.findIndex(x => x.id === m.id);
  if (idx >= 0) state.members[idx] = m;
  else state.members.unshift(m);
} else if (action === 'UPSERT_PROSPECT') {
  const p = Object.assign({}, payload);
  if (!p.id) p.id = 'p-' + Date.now();
  if (!p.createdAt) p.createdAt = new Date().toISOString();
  const idx = state.prospects.findIndex(x => x.id === p.id);
  if (idx >= 0) state.prospects[idx] = p;
  else state.prospects.unshift(p);
} else if (action === 'LOG_DAIMOKU_TIMER') {
  const pid = String(payload.prospectId || 'p-1');
  const added = parseInt(payload.addedSeconds || 0, 10);
  const p = state.prospects.find(x => x.id === pid);
  if (p) p.chantingSeconds = (p.chantingSeconds || 0) + Math.max(0, added);
} else if (action === 'UPSERT_ZADANKAI') {
  const z = Object.assign({}, payload, { createdAt: new Date().toISOString() });
  state.zadankai = [z].concat((state.zadankai || []).filter(x => x.month !== z.month));
} else if (action === 'UPSERT_GUIDANCE') {
  const g = Object.assign({ id: 'g-' + Date.now(), createdAt: new Date().toISOString() }, payload);
  state.guidance.unshift(g);
} else if (action === 'SUMMARIZE_STUDY_IMAGE') {
  const clip = {
    id: 'g-' + Date.now(),
    rawText: "Winter always turns to spring. Never, from ancient times on, has anyone heard or seen of winter turning back into autumn. (The Writings of Nichiren Daishonin, Vol. 1, p. 536)",
    summaryText: "• Every hardship in faith is temporary and inevitably blossoms into victory ('spring').\n• Continuing resolute Daimoku transforms karma into mission.",
    category: "Overcoming Obstacles",
    createdAt: new Date().toISOString()
  };
  state.guidance.unshift(clip);
  extraResponse = clip;
} else if (action === 'TRANSCRIBE_VOICE_MEMO') {
  const clip = {
    id: 'g-' + Date.now(),
    rawText: "Chanted 30 minutes of vibrant Daimoku for the health and victory of every family in Salt Lake Chapter. Shared Ikeda Sensei's guidance on 'Winter Always Turns to Spring' to prepare for this month's Zadankai.",
    summaryText: "• Voice memo transcribed with SGI/BSG Buddhist terminology (Daimoku, Zadankai, Ikeda Sensei).",
    category: "Voice Reflection",
    createdAt: new Date().toISOString()
  };
  state.guidance.unshift(clip);
  extraResponse = clip;
} else if (action === 'ZADANKAI_ROTATION') {
  extraResponse = {
    recommendations: [
      { role: "Emcee", memberIdOrName: "Amit Sen", explanation: "Has not served as Emcee in recent Zadankai meetings; fresh youth division energy." },
      { role: "Experience", memberIdOrName: "Saurav Kumar", explanation: "Accomplished breakthrough in securing Senior Designer position after 6 months of Daimoku." },
      { role: "Significance", memberIdOrName: "Mrs. Deepti Bannerjee", explanation: "Improved health challenge and arranged companion transport; inspiring pioneer spirit." },
      { role: "Festoon", memberIdOrName: "Suresh Pillai", explanation: "Warm encouragement role anchoring district unity." },
      { role: "Song", memberIdOrName: "Amit Sen", explanation: "High-spirited chorus leadership." },
      { role: "FD Activity", memberIdOrName: "Mrs. Deepti Bannerjee", explanation: "Warm rapport with Future Division young phoenixes." }
    ],
    districtConceptTheme: "May 3rd Soka Gakkai Day: Turning Every Obstacle into a Victory of the Heart"
  };
} else if (action === 'BODHISATTVA_CHAT') {
  const q = String(payload.query || '').toLowerCase();
  const matched = (state.members || []).find(m => q.includes(m.name.toLowerCase()) || q.includes(m.name.split(' ')[0].toLowerCase())) || state.members[0];
  const quote = (state.guidance && state.guidance[0]) ? state.guidance[0].rawText : SEED_STATE.guidance[0].rawText;
  extraResponse = {
    reply: `Compassionate Care Plan for ${matched.name} (${matched.district}):\n\n` +
      `1. Current Life State (${matched.challengeStatus}):\n` +
      `• Challenge: ${matched.activeChallenge}\n` +
      (matched.resolutionNotes ? `• Breakthrough Progress: ${matched.resolutionNotes}\n` : '') +
      `\n2. Recommended Gosho & Ikeda Sensei Guidance:\n"${quote}"\n\n` +
      `3. Suggested Bodhisattva Action:\nSchedule a warm 20-minute Daimoku visit or call during their preferred window (${matched.visitPref || 'Weekends'}). Remind ${matched.name} that chanting Nam-myoho-renge-kyo turns every obstacle into mission!`
  };
} else if (action === 'GDPR_ERASURE') {
  const email = String(payload.email || '').trim().toLowerCase();
  const beforeCount = state.members.length;
  state.members = state.members.filter(m => String(m.email || '').trim().toLowerCase() !== email);
  extraResponse = {
    erasureReceiptId: 'erasure-' + Date.now(),
    subjectEmail: email,
    recordsPurged: beforeCount - state.members.length,
    executedAt: new Date().toISOString()
  };
}

const liveMins = Math.floor((state.prospects || []).reduce((acc, p) => acc + (p.chantingSeconds || 0), 0) / 60);
state.daimokuWeekly = [
  { label: "Wk 14", minutes: 120 },
  { label: "Wk 15", minutes: 185 },
  { label: "Wk 16", minutes: 240 },
  { label: "Wk 17 (Now)", minutes: 90 + liveMins }
];
state.daimokuMonthly = [
  { label: "2026-02", minutes: 450 },
  { label: "2026-03", minutes: 680 },
  { label: "2026-04", minutes: 890 },
  { label: "2026-05 (Now)", minutes: 310 + liveMins }
];

const safeJsonLiteral = JSON.stringify(state).replace(/'/g, "''");
const combinedSql = `INSERT INTO bsg_sangha_cloud_store (store_key, state_json, updated_at) VALUES ('primary_district_state', '${safeJsonLiteral}'::jsonb, NOW()) ON CONFLICT (store_key) DO UPDATE SET state_json = EXCLUDED.state_json, updated_at = NOW();`;

return [{
  json: {
    combinedSql,
    apiResponse: Object.assign({ status: "ok", state }, extraResponse)
  }
}];
